"""Run manifest: everything needed to know what a run was and to reproduce it."""

from __future__ import annotations

import hashlib
import importlib.metadata as md
import json
import os
import platform
import subprocess
import sys
from datetime import UTC, datetime
from pathlib import Path

from . import __version__

MANIFEST_SCHEMA = "cl-workbench/manifest/v1"

DATA_LABEL_NOTES = {
    "SYNTHETIC": "Generated by the cl-sdk simulator's random data source (Poisson noise with "
    "threshold-crossing 'spikes'). Not a recording of living neurons.",
    "REPLAYED": "Replayed from an existing HDF5 file by the cl-sdk simulator. The replay ignores "
    "stimulation. acquisition.replay_source records the source file's path, size and SHA-256; "
    "these identify the file used, not its origin, authenticity or whether it came from living neurons.",
}


def utc_now() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds")


def sha256_file(path: Path, chunk: int = 1 << 20) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while block := f.read(chunk):
            h.update(block)
    return h.hexdigest()


def file_entry(path: Path) -> dict:
    return {"sha256": sha256_file(path), "bytes": path.stat().st_size}


def git_info(start: Path | None = None) -> dict:
    """Commit and dirty flag of the workbench source tree, if it is a git checkout."""
    here = Path(start or Path(__file__).resolve().parent)
    try:
        commit = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=here, capture_output=True, text=True, timeout=10
        )
        if commit.returncode != 0:
            return {"git_commit": None, "git_dirty": None, "note": "not a git checkout or no commits"}
        status = subprocess.run(
            ["git", "status", "--porcelain", "--untracked-files=no"], cwd=here,
            capture_output=True, text=True, timeout=10,
        )
        return {"git_commit": commit.stdout.strip(), "git_dirty": bool(status.stdout.strip())}
    except (OSError, subprocess.SubprocessError) as exc:
        return {"git_commit": None, "git_dirty": None, "note": f"git unavailable: {exc}"}


def environment_info() -> dict:
    packages = {}
    for dist in md.distributions():
        name = dist.metadata["Name"]
        if name:
            packages[name.lower()] = dist.version
    return {
        "python": sys.version.split()[0],
        "python_implementation": platform.python_implementation(),
        "platform": platform.platform(),
        "machine": platform.machine(),
        "cpu_count": os.cpu_count(),
        "packages": dict(sorted(packages.items())),
    }


def code_info() -> dict:
    return {"workbench_version": __version__, **git_info()}


def write_json(path: Path, data: dict) -> None:
    path.write_text(json.dumps(data, indent=2, sort_keys=False, default=str) + "\n")


def metrics_digest(metrics: dict) -> str:
    blob = json.dumps(metrics, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(blob.encode()).hexdigest()
